# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import find_gaps, gap_labels

OPEN = parse_span("08:00-18:00")

class GapTests(unittest.TestCase):
    def test_no_shifts_is_one_big_gap(self):
        self.assertEqual(gap_labels([], OPEN), [
            "gap 08:00-18:00 (600 min)"
        ])

    def test_gap_between_shifts(self):
        worked = [
            parse_span("08:00-12:00"),
            parse_span("13:00-18:00")
        ]
        self.assertEqual(gap_labels(worked, OPEN), [
            "gap 12:00-13:00 (60 min)"
        ])

    def test_edges_and_unsorted_input(self):
        worked = [
            parse_span("14:00-16:00"),
            parse_span("09:00-12:00"),
            parse_span("11:00-13:00")
        ]
        self.assertEqual(gap_labels(worked, OPEN), [
            "gap 08:00-09:00 (60 min)",
            "gap 13:00-14:00 (60 min)",
            "gap 16:00-18:00 (120 min)"
        ])

    def test_full_cover_has_no_gaps(self):
        worked = [
            parse_span("08:00-13:00"),
            parse_span("13:00-18:00")
        ]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_span_outside_hours_raises(self):
        for text in ("07:00-09:00", "17:00-19:00"):
            with self.assertRaises(ValueError):
                gap_labels([parse_span(text)], OPEN)

    def test_find_gaps_returns_spans(self):
        found = find_gaps([Span(480, 600)], OPEN)
        self.assertEqual(found, [Span(600, 1080)])
